'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import { useCart } from '@/components/consumer/Cart'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import { harvestClock } from '@/lib/harvest'
import { normalizePickupSchedule } from '@/lib/pickup-slots'

// Two compact harvest tables shown above the consumer search box:
//   FreshHarvestsTable    — already-picked harvests (buyable now), newest first
//   UpcomingHarvestsTable — future/pre-book harvests, soonest first
// Each row is one HARVEST (its own product): tapping it opens that harvest's
// detail page, and the cart icon adds that specific harvest — so two harvests of
// the same produce are independent. They read the `harvests` table (see
// scripts/harvests-migration.sql) and silently render nothing when the table
// isn't present yet or there are no matching harvests.

type Listing = {
  id: string
  name: string
  emoji?: string | null
  status?: string | null
}

type HarvestRow = {
  id: string
  harvested_at: string
  produce_listing_id: string
  stock_qty?: number | null
  shelf_life_days?: number | null
  // PostgREST embeds the parent listing as an object (many-to-one).
  produce_listings?: Listing | Listing[] | null
}

const DAY = 86_400_000
type Variant = 'fresh' | 'upcoming'

function HarvestTable({ variant }: { variant: Variant }) {
  const { lang, L } = useLang()
  const router = useRouter()
  const { addItem, cart } = useCart()
  const { requireAuth } = useConsumerAuth()
  const [rows, setRows] = useState<HarvestRow[]>([])
  const [loaded, setLoaded] = useState(false)
  // Listing ids currently being fetched-and-added, so the cart icon can show a
  // spinner and ignore double taps.
  const [adding, setAdding] = useState<Record<string, boolean>>({})

  useEffect(() => {
    let cancelled = false
    const now = Date.now()
    const base = supabase
      .from('harvests')
      .select('id, harvested_at, produce_listing_id, stock_qty, shelf_life_days, produce_listings!inner(id, name, emoji, status)')
      .eq('produce_listings.status', 'available')
    // Fresh = picked within the last 2 days, newest first.
    // Upcoming = picks in the next 7 days (pre-book), soonest first.
    const q =
      variant === 'fresh'
        ? base
            .gte('harvested_at', new Date(now - 2 * DAY).toISOString())
            .lte('harvested_at', new Date(now).toISOString())
            .order('harvested_at', { ascending: false })
        : base
            .gt('harvested_at', new Date(now).toISOString())
            .lte('harvested_at', new Date(now + 7 * DAY).toISOString())
            .order('harvested_at', { ascending: true })
    q.limit(12).then(({ data }) => {
      if (cancelled) return
      setRows((data ?? []) as HarvestRow[])
      setLoaded(true)
    })
    return () => { cancelled = true }
  }, [variant])

  // One listing from the embed (handle either object or single-element array).
  const listingOf = (r: HarvestRow): Listing | null => {
    const l = r.produce_listings
    if (!l) return null
    return Array.isArray(l) ? (l[0] ?? null) : l
  }

  // Add THIS harvest to the cart from the table (keyed by harvest id, so two
  // harvests of the same produce are separate cart lines). The row holds the
  // harvest's own stock/date; we fetch price tiers + farmer from the template on
  // tap. requireAuth gates it behind consumer login.
  const addHarvestToCart = (r: HarvestRow) => {
    if (adding[r.id]) return
    requireAuth(async () => {
      setAdding((s) => ({ ...s, [r.id]: true }))
      const { data: listing } = await supabase
        .from('produce_listings')
        .select('id, name, variety, emoji, unit, price_tier_1_qty, price_tier_1_price, price_tier_2_qty, price_tier_2_price, price_tier_3_price, farmer_id')
        .eq('id', r.produce_listing_id)
        .single()
      if (!listing) { setAdding((s) => ({ ...s, [r.id]: false })); return }
      const { data: farmer } = await supabase
        .from('farmers')
        .select('id, name, phone, village, slug, pickup_locations, pickup_slots')
        .eq('id', listing.farmer_id)
        .single()
      setAdding((s) => ({ ...s, [r.id]: false }))
      if (!farmer?.phone || !listing.price_tier_1_price) return
      addItem({
        listingId: listing.id,
        harvestId: r.id,
        harvestedAt: r.harvested_at,
        shelfLifeDays: r.shelf_life_days ?? undefined,
        name: listing.name,
        variety: listing.variety,
        emoji: listing.emoji,
        unit: listing.unit ?? undefined,
        stockQty: r.stock_qty ?? undefined,
        pricePerKg: listing.price_tier_1_price,
        priceTier1Qty: listing.price_tier_1_qty,
        priceTier1Price: listing.price_tier_1_price,
        priceTier2Qty: listing.price_tier_2_qty,
        priceTier2Price: listing.price_tier_2_price,
        priceTier3Price: listing.price_tier_3_price,
        farmerId: farmer.id,
        farmerName: farmer.name,
        farmerPhone: farmer.phone,
        farmerVillage: farmer.village ?? '',
        farmerSlug: farmer.slug,
        farmerPickupLocations: farmer.pickup_locations ?? [],
        farmerPickupSlots: normalizePickupSchedule(farmer.pickup_slots, farmer.pickup_locations ?? []),
      }, 1)
    })
  }

  if (!loaded || rows.length === 0) return null

  const title = variant === 'fresh'
    ? L('Fresh Harvests near you', 'మీ దగ్గర తాజా కోతలు')
    : L('Upcoming Harvests', 'రాబోయే కోతలు')
  const icon = variant === 'fresh' ? '🌾' : '🌱'
  const hint = variant === 'fresh' ? L('Freshest first', 'తాజావి ముందు') : L('Soonest first', 'త్వరలో వచ్చేవి')
  const whenLabel = variant === 'fresh' ? L('When', 'ఎప్పుడు') : L('Expected', 'అంచనా')

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden self-start">
      <div className="px-4 pt-4 pb-2 flex items-baseline justify-between gap-2">
        <h2 className="text-base font-extrabold text-gray-900">
          {icon} {title}
        </h2>
        <span className="text-[11px] text-gray-500 whitespace-nowrap">{hint}</span>
      </div>

      <table className="w-full text-left border-collapse">
        <thead>
          <tr className="text-[10px] uppercase tracking-wide text-gray-400 border-b border-gray-100">
            <th className="font-bold px-4 py-2">{L('Harvest', 'కోత')}</th>
            <th className="font-bold px-4 py-2 text-right">{whenLabel}</th>
            <th className="w-10" aria-hidden="true"></th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const item = listingOf(r)
            if (!item) return null
            return (
              <tr
                key={r.id}
                onClick={() => router.push(`/consumer/harvest/${r.id}`)}
                className="border-b border-gray-50 last:border-0 cursor-pointer active:bg-green-50"
              >
                <td className="pl-4 pr-2 py-3">
                  <span className="flex items-center gap-1.5 min-w-0">
                    <span className="text-lg shrink-0">{item.emoji || '🌿'}</span>
                    <span className="text-sm font-bold text-gray-900 truncate">
                      {localizeName(item.name, lang)}
                    </span>
                  </span>
                </td>
                <td className="px-2 py-3 text-right align-middle">
                  <span className={`text-[11px] font-semibold whitespace-nowrap ${variant === 'fresh' ? 'text-green-700' : 'text-blue-700'}`}>
                    ⏱ {harvestClock(r.harvested_at, L)}
                  </span>
                </td>
                {/* Add-to-cart — adds THIS harvest (keyed by harvest id, so the
                    fresh and upcoming rows don't mirror each other). stopPropagation
                    so it doesn't also open the details row. */}
                <td className="pr-3 pl-1 py-3 text-right align-middle">
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); void addHarvestToCart(r) }}
                    disabled={!!adding[r.id]}
                    aria-label={L('Add to cart', 'బుట్టలో వేయండి')}
                    className={`inline-flex items-center justify-center w-8 h-8 rounded-full active:scale-95 disabled:opacity-50 ${
                      cart[r.id] ? 'bg-green-600 text-white' : 'bg-green-50 text-green-700'
                    }`}
                  >
                    {adding[r.id] ? (
                      <span className="text-xs leading-none">…</span>
                    ) : cart[r.id] ? (
                      <span className="text-sm leading-none">✓</span>
                    ) : (
                      <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                        <circle cx="9" cy="20" r="1.4" />
                        <circle cx="18" cy="20" r="1.4" />
                        <path d="M2.5 3h2l2.2 12.1a1.5 1.5 0 0 0 1.5 1.2h8.4a1.5 1.5 0 0 0 1.5-1.2L21 7H6" />
                      </svg>
                    )}
                  </button>
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>

      {/* Hint so it's clear the rows are tappable. */}
      <p className="px-4 pb-3 pt-1 text-[11px] text-gray-400">
        {L('Tap a harvest to see full details', 'పూర్తి వివరాల కోసం కోతను నొక్కండి')}
      </p>
    </div>
  )
}

export function FreshHarvestsTable() {
  return <HarvestTable variant="fresh" />
}

export function UpcomingHarvestsTable() {
  return <HarvestTable variant="upcoming" />
}

export default FreshHarvestsTable

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { supabase } from '@/lib/supabase'
import { useCart } from '@/components/consumer/Cart'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import { harvestClock, freshnessLabel } from '@/lib/harvest'
import { normalizePickupSchedule } from '@/lib/pickup-slots'

// "Today's Harvest near you" — the freshness-driven USP feed. Lists harvests
// from the last 2 days (buyable now) plus the next 3 days (pre-book), newest
// pick first, each with the "Harvested 2h ago" clock. Each card is one harvest
// and taps through to that harvest's own detail page. Reads the `harvests`
// table (see scripts/harvests-migration.sql); silently renders nothing if the
// table/migration isn't present yet.

type Listing = {
  id: string
  name: string
  variety?: string | null
  emoji?: string | null
  image_url?: string | null
  image_urls?: string[] | null
  method?: string | null
  status?: string | null
  price_tier_1_price?: number | null
  unit?: string | null
  shelf_life_days?: number | null
}

type HarvestRow = {
  id: string
  harvested_at: string
  shelf_life_days?: number | null
  approx_quantity?: number | null
  stock_qty?: number | null
  unit?: string | null
  produce_listing_id: string
  // PostgREST embeds the parent listing as an object (many-to-one).
  produce_listings?: Listing | Listing[] | null
}

const DAY = 86_400_000

export default function TodaysHarvest() {
  const { lang, L } = useLang()
  const { addItem, cart } = useCart()
  const { requireAuth } = useConsumerAuth()
  const [rows, setRows] = useState<HarvestRow[]>([])
  const [loaded, setLoaded] = useState(false)
  // Harvest ids mid add-to-cart, so the button can show progress / ignore taps.
  const [adding, setAdding] = useState<Record<string, boolean>>({})

  useEffect(() => {
    let cancelled = false
    const start = new Date(Date.now() - 2 * DAY).toISOString()
    const end = new Date(Date.now() + 3 * DAY).toISOString()
    supabase
      .from('harvests')
      .select('id, harvested_at, shelf_life_days, approx_quantity, stock_qty, unit, produce_listing_id, produce_listings!inner(id, name, variety, emoji, image_url, image_urls, method, status, price_tier_1_price, unit, shelf_life_days)')
      .gte('harvested_at', start)
      .lte('harvested_at', end)
      .eq('produce_listings.status', 'available')
      .order('harvested_at', { ascending: false })
      .limit(30)
      .then(({ data }) => {
        if (cancelled) return
        setRows((data ?? []) as HarvestRow[])
        setLoaded(true)
      })
    return () => { cancelled = true }
  }, [])

  // One listing from the embed (handle either object or single-element array).
  const listingOf = (r: HarvestRow): Listing | null => {
    const l = r.produce_listings
    if (!l) return null
    return Array.isArray(l) ? (l[0] ?? null) : l
  }

  // Add THIS harvest to the cart (keyed by harvest id). Fetches price tiers +
  // farmer from the template on tap; uses the harvest's own stock. requireAuth
  // gates it behind consumer login.
  const addHarvestToCart = (r: HarvestRow) => {
    if (adding[r.id]) return
    requireAuth(async () => {
      setAdding((s) => ({ ...s, [r.id]: true }))
      const { data: listing } = await supabase
        .from('produce_listings')
        .select('id, name, variety, emoji, unit, price_tier_1_qty, price_tier_1_price, price_tier_2_qty, price_tier_2_price, price_tier_3_price, farmer_id')
        .eq('id', r.produce_listing_id)
        .single()
      if (!listing) { setAdding((s) => ({ ...s, [r.id]: false })); return }
      const { data: farmer } = await supabase
        .from('farmers')
        .select('id, name, phone, village, slug, pickup_locations, pickup_slots')
        .eq('id', listing.farmer_id)
        .single()
      setAdding((s) => ({ ...s, [r.id]: false }))
      if (!farmer?.phone || !listing.price_tier_1_price) return
      addItem({
        listingId: listing.id,
        harvestId: r.id,
        harvestedAt: r.harvested_at,
        shelfLifeDays: r.shelf_life_days ?? undefined,
        name: listing.name,
        variety: listing.variety,
        emoji: listing.emoji,
        unit: listing.unit ?? undefined,
        stockQty: r.stock_qty ?? undefined,
        pricePerKg: listing.price_tier_1_price,
        priceTier1Qty: listing.price_tier_1_qty,
        priceTier1Price: listing.price_tier_1_price,
        priceTier2Qty: listing.price_tier_2_qty,
        priceTier2Price: listing.price_tier_2_price,
        priceTier3Price: listing.price_tier_3_price,
        farmerId: farmer.id,
        farmerName: farmer.name,
        farmerPhone: farmer.phone,
        farmerVillage: farmer.village ?? '',
        farmerSlug: farmer.slug,
        farmerPickupLocations: farmer.pickup_locations ?? [],
        farmerPickupSlots: normalizePickupSchedule(farmer.pickup_slots, farmer.pickup_locations ?? []),
      }, 1)
    })
  }

  const now = Date.now()
  // Split into two sides: already-picked (buyable now, hottest first) and
  // upcoming (pre-book, soonest first).
  const freshRows = rows
    .filter((r) => new Date(r.harvested_at).getTime() <= now)
    .sort((a, b) => new Date(b.harvested_at).getTime() - new Date(a.harvested_at).getTime())
  const upcomingRows = rows
    .filter((r) => new Date(r.harvested_at).getTime() > now)
    .sort((a, b) => new Date(a.harvested_at).getTime() - new Date(b.harvested_at).getTime())

  if (!loaded || (freshRows.length === 0 && upcomingRows.length === 0)) return null

  // One harvest card. Fresh picks get a 🔥 "hot" badge; upcoming get "Pre-book".
  const renderCard = (r: HarvestRow, kind: 'fresh' | 'upcoming') => {
    const item = listingOf(r)
    if (!item) return null
    const emoji = item.emoji || '🌿'
    const cover = (item.image_urls && item.image_urls.length ? item.image_urls[0] : item.image_url) || null
    const clock = harvestClock(r.harvested_at, L)
    const fresh = freshnessLabel(r.harvested_at, r.shelf_life_days ?? item.shelf_life_days ?? null, L)
    return (
      <Link
        key={r.id}
        href={`/consumer/harvest/${r.id}`}
        className="snap-start shrink-0 w-36 bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden active:opacity-80"
      >
        <div className="h-24 w-full bg-green-50 flex items-center justify-center relative">
          {cover ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={cover} alt={item.name} loading="lazy" className="w-full h-full object-cover" />
          ) : (
            <span className="text-4xl">{emoji}</span>
          )}
          {kind === 'fresh' ? (
            <span className="absolute top-1.5 left-1.5 bg-orange-500 text-white text-[10px] font-bold rounded-full px-1.5 py-0.5">
              🔥
            </span>
          ) : (
            <span className="absolute top-1.5 left-1.5 bg-blue-600 text-white text-[9px] font-bold rounded-full px-1.5 py-0.5">
              {L('Pre-book', 'ముందస్తు')}
            </span>
          )}
          {/* Add-to-cart — adds THIS harvest without leaving the page.
              preventDefault/stopPropagation so it doesn't follow the card link. */}
          <button
            type="button"
            onClick={(e) => { e.preventDefault(); e.stopPropagation(); addHarvestToCart(r) }}
            disabled={!!adding[r.id]}
            aria-label={L('Add to cart', 'బుట్టలో వేయండి')}
            className={`absolute top-1.5 right-1.5 inline-flex items-center justify-center w-7 h-7 rounded-full shadow active:scale-95 disabled:opacity-50 ${
              cart[r.id] ? 'bg-green-600 text-white' : 'bg-white text-green-700'
            }`}
          >
            {adding[r.id] ? (
              <span className="text-[10px] leading-none">…</span>
            ) : cart[r.id] ? (
              <span className="text-xs leading-none">✓</span>
            ) : (
              <svg viewBox="0 0 24 24" className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <circle cx="9" cy="20" r="1.4" />
                <circle cx="18" cy="20" r="1.4" />
                <path d="M2.5 3h2l2.2 12.1a1.5 1.5 0 0 0 1.5 1.2h8.4a1.5 1.5 0 0 0 1.5-1.2L21 7H6" />
              </svg>
            )}
          </button>
        </div>
        <div className="p-2">
          <p className="text-[13px] font-bold text-gray-900 truncate">{localizeName(item.name, lang)}</p>
          <p className={`text-[10px] font-semibold truncate mt-0.5 ${kind === 'fresh' ? 'text-green-700' : 'text-blue-700'}`}>⏱ {clock}</p>
          {fresh && <p className="text-[10px] text-amber-700 truncate">{fresh}</p>}
          {item.price_tier_1_price != null && (
            <p className="text-xs font-extrabold text-green-800 mt-0.5">₹{item.price_tier_1_price}<span className="text-[10px] font-medium text-gray-400">/{item.unit || 'kg'}</span></p>
          )}
        </div>
      </Link>
    )
  }

  return (
    <section className="mb-4">
      <h2 className="text-base font-extrabold text-gray-900 px-1 mb-2">
        🌾 {L("Today's Harvest near you", 'మీ దగ్గర ఈరోజు కోత')}
      </h2>

      {/* Fresh on one side, Upcoming on the other (stacked on mobile). Each side
          renders nothing when it has no harvests. */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
        {freshRows.length > 0 && (
          <div>
            <div className="flex items-baseline justify-between px-1 mb-1.5">
              <h3 className="text-sm font-extrabold text-gray-900">🔥 {L('Fresh Harvests', 'తాజా కోతలు')}</h3>
              <span className="text-[11px] text-gray-500">{L('Freshest first', 'తాజావి ముందు')}</span>
            </div>
            <div className="flex gap-3 overflow-x-auto scrollbar-hide pb-1 -mx-1 px-1 snap-x">
              {freshRows.map((r) => renderCard(r, 'fresh'))}
            </div>
          </div>
        )}
        {upcomingRows.length > 0 && (
          <div>
            <div className="flex items-baseline justify-between px-1 mb-1.5">
              <h3 className="text-sm font-extrabold text-gray-900">🌱 {L('Upcoming Harvests', 'రాబోయే కోతలు')}</h3>
              <span className="text-[11px] text-gray-500">{L('Soonest first', 'త్వరలో వచ్చేవి')}</span>
            </div>
            <div className="flex gap-3 overflow-x-auto scrollbar-hide pb-1 -mx-1 px-1 snap-x">
              {upcomingRows.map((r) => renderCard(r, 'upcoming'))}
            </div>
          </div>
        )}
      </div>
    </section>
  )
}

'use client'

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import Link from 'next/link'
import GlobalNav from '@/components/consumer/GlobalNav'
import { CartFab, useCart } from '@/components/consumer/Cart'
import MyOrdersChip from '@/components/consumer/MyOrdersChip'
import RoleGateModal from '@/components/consumer/RoleGateModal'
import ProduceReviewsModal from '@/components/consumer/ProduceReviewsModal'
import ShareButton from '@/components/consumer/ShareButton'
import FreshHarvestsTable, { UpcomingHarvestsTable } from '@/components/consumer/FreshHarvestsTable'
import { supabase } from '@/lib/supabase'
import { haversineKm, nearestTown, formatDistance, farmerCoords } from '@/lib/location'
import LocationSearch from '@/components/LocationSearch'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import { harvestClock, freshnessLabel } from '@/lib/harvest'
import { normalizePickupSchedule } from '@/lib/pickup-slots'

type Farmer = {
  id: string
  name: string
  village: string
  slug: string
  phone: string
  method: string
  pickup_locations?: string[] | null
  pickup_slots?: unknown
  lat?: number | null
  lng?: number | null
}

type ProduceListing = {
  id: string
  name: string
  variety?: string
  emoji?: string
  image_url?: string
  image_urls?: string[] | null
  method?: string
  status: string
  price_tier_1_price?: number
  price_tier_1_qty?: number
  price_tier_2_price?: number
  price_tier_2_qty?: number
  price_tier_3_price?: number
  price_tier_3_qty?: number
  stock_qty?: number
  unit?: string
  available_to?: string
  rating_avg?: number | null
  review_count?: number | null
  // Non-cancelled/declined order count for this listing — powers "sort by
  // Purchases". Attached by /api/produce and /api/produce/search.
  purchase_count?: number | null
  farmer_id: string
  farmer?: Farmer
  // Shelf life set on the listing itself (produce Edit form) — used as the
  // fallback when the latest logged harvest doesn't carry its own.
  shelf_life_days?: number | null
  // Harvest date/time set on the listing itself (produce Edit form). Drives the
  // clock when no separate `harvests` row has been logged for this produce.
  harvest_date?: string | null
  // Latest harvest for this produce (template), attached client-side from the
  // `harvests` table — drives the "Harvested 2 hours ago" clock on the card.
  latest_harvested_at?: string | null
  latest_shelf_life_days?: number | null
}

const CATEGORIES = [
  { key: 'all',        en: 'All',             te: 'అన్నీ' },
  { key: 'vegetables', en: 'Vegetables',      te: 'కూరగాయలు' },
  { key: 'fruits',     en: 'Fruits',          te: 'పళ్ళు' },
  { key: 'grains',     en: 'Grains & Pulses', te: 'ధాన్యాలు' },
  { key: 'leafy',      en: 'Leafy Greens',    te: 'ఆకు కూరలు' },
  { key: 'spices',     en: 'Spices',          te: 'మసాలాలు' },
  { key: 'other',      en: 'Other',           te: 'ఇతర' },
]

// Short, single-word method label for the small pill on the image corner.
const METHOD_SHORT: Record<string, string> = {
  natural:      'Natural',
  organic:      'Organic',
  low_chemical: 'Semi-org',
  chemical:     'Chemical',
}

// Solid pill colour for the method badge over the image (spec: natural=green,
// organic=blue). White text sits on a solid colour so it reads over any photo.
const METHOD_PILL: Record<string, string> = {
  natural:      'bg-green-600 text-white',
  organic:      'bg-blue-600 text-white',
  low_chemical: 'bg-amber-500 text-white',
  chemical:     'bg-red-500 text-white',
}

// Image-area background tint by produce type, used only for the emoji
// fallback (no photo). Fruits=yellow, vegetables=pink, leafy greens=green.
const PRODUCE_BG: Record<string, string> = {
  '🍌': '#fff8e1', '🥭': '#fff8e1', '🍓': '#fff8e1', '🥥': '#fff8e1', '🍇': '#fff8e1', '🍋': '#fff8e1', // fruits
  '🍅': '#fce4ec', '🍆': '#fce4ec', '🫑': '#fce4ec', '🥕': '#fce4ec', '🌽': '#fce4ec', '🧅': '#fce4ec', '🧄': '#fce4ec', // vegetables
  '🥬': '#e8f5e9', '🥦': '#e8f5e9', '🌿': '#e8f5e9', '🫒': '#e8f5e9', // leafy greens
}
const DEFAULT_PRODUCE_BG = '#f5f5f5'

export default function ConsumerPage() {
  const { L } = useLang()
  const [available, setAvailable]     = useState<ProduceListing[]>([])
  const [comingSoon, setComingSoon]   = useState<ProduceListing[]>([])
  // Latest harvest per produce (listing id → harvest), for the "Harvested 2h
  // ago" clock on each card. Best-effort from the `harvests` table.
  const [harvestMap, setHarvestMap]   = useState<Record<string, { at: string; shelf: number | null }>>({})
  const [filtered, setFiltered]       = useState<ProduceListing[]>([])
  const [search, setSearch]           = useState('')
  const [method, setMethod]           = useState('all')
  const [category, setCategory]       = useState('all')
  // Harvest-list sort + farmer filter (Trello: sort/filter the harvests list).
  const [sortBy, setSortBy]           = useState<'fresh' | 'rating' | 'purchases'>('fresh')
  const [farmerFilter, setFarmerFilter] = useState('all')
  const [loading, setLoading]         = useState(true)
  const [farmerCount, setFarmerCount] = useState(0)
  const searchAbortRef = useRef<AbortController | null>(null)

  // Consumer location
  const [consumerLat, setConsumerLat]           = useState<number | null>(null)
  const [consumerLng, setConsumerLng]           = useState<number | null>(null)
  const [consumerLocationName, setConsumerLocationName] = useState('')
  const [showLocationSheet, setShowLocationSheet]       = useState(false)
  const [distanceFilter, setDistanceFilter]             = useState<number | null>(null)

  const fetchData = useCallback(async (silent = false) => {
    if (!silent) setLoading(true)
    try {
      const [avRes, csRes] = await Promise.all([
        fetch('/api/produce', { cache: 'no-store' }),
        fetch('/api/produce?status=coming_soon', { cache: 'no-store' }),
      ])
      const av: ProduceListing[] = await avRes.json().catch(() => [])
      const cs: ProduceListing[] = await csRes.json().catch(() => [])
      const avArr = Array.isArray(av) ? av : []
      const csArr = Array.isArray(cs) ? cs : []
      setAvailable(avArr)
      setFiltered(avArr)
      setComingSoon(csArr)
      setFarmerCount(new Set(avArr.map((p) => p.farmer_id)).size)

      // Latest harvest per produce → the card clock. Best-effort: a missing
      // `harvests` table (migration not applied) just leaves the map empty.
      try {
        const since = new Date(Date.now() - 14 * 86_400_000).toISOString()
        const { data: hs } = await supabase
          .from('harvests')
          .select('produce_listing_id, harvested_at, shelf_life_days')
          .gte('harvested_at', since)
          .order('harvested_at', { ascending: false })
          .limit(500)
        const map: Record<string, { at: string; shelf: number | null }> = {}
        for (const h of (hs ?? []) as { produce_listing_id: string; harvested_at: string; shelf_life_days: number | null }[]) {
          if (!map[h.produce_listing_id]) {
            map[h.produce_listing_id] = { at: h.harvested_at, shelf: h.shelf_life_days ?? null }
          }
        }
        setHarvestMap(map)
      } catch { /* harvests table not present yet */ }
    } catch { /* silent */ }
    if (!silent) setLoading(false)
  }, [])

  useEffect(() => {
    fetchData()
    // Background refreshes — no skeleton flash
    const onVisible = () => { if (document.visibilityState === 'visible') fetchData(true) }
    document.addEventListener('visibilitychange', onVisible)
    const channel = supabase
      .channel('produce_listings_consumer')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'produce_listings' }, () => fetchData(true))
      .subscribe()
    return () => {
      document.removeEventListener('visibilitychange', onVisible)
      supabase.removeChannel(channel)
    }
  }, [fetchData])

  const doSearch = useCallback(async () => {
    if (!search && method === 'all' && category === 'all') {
      setFiltered(available)
      return
    }
    searchAbortRef.current?.abort()
    searchAbortRef.current = new AbortController()
    try {
      const p = new URLSearchParams()
      if (search)              p.set('q', search)
      if (method !== 'all')    p.set('method', method)
      if (category !== 'all')  p.set('category', category)
      const res = await fetch(`/api/produce/search?${p}`, { cache: 'no-store', signal: searchAbortRef.current.signal })
      const data = await res.json().catch(() => [])
      setFiltered(Array.isArray(data) ? data : [])
    } catch (e) {
      if ((e as Error).name !== 'AbortError') { /* silent */ }
    }
  }, [search, method, category, available])

  useEffect(() => {
    const t = setTimeout(doSearch, 300)
    return () => clearTimeout(t)
  }, [doSearch])

  // Load consumer location from localStorage
  useEffect(() => {
    const lat  = localStorage.getItem('yff_consumer_lat')
    const lng  = localStorage.getItem('yff_consumer_lng')
    const name = localStorage.getItem('yff_consumer_location_name')
    if (lat && lng) {
      setConsumerLat(Number(lat))
      setConsumerLng(Number(lng))
      setConsumerLocationName(name ?? '')
    } else if (!localStorage.getItem('yff_location_prompted')) {
      setShowLocationSheet(true)
    }
  }, [])

  const saveConsumerLocation = useCallback((lat: number, lng: number, name: string) => {
    setConsumerLat(lat)
    setConsumerLng(lng)
    setConsumerLocationName(name)
    localStorage.setItem('yff_consumer_lat', String(lat))
    localStorage.setItem('yff_consumer_lng', String(lng))
    localStorage.setItem('yff_consumer_location_name', name)
    localStorage.setItem('yff_location_prompted', '1')
    setShowLocationSheet(false)
  }, [])

  // Farmers present in the current harvest list → the "Filter by farmer" options.
  const farmerOptions = useMemo(() => {
    const m = new Map<string, string>()
    for (const p of available) {
      if (p.farmer_id && p.farmer?.name) m.set(p.farmer_id, p.farmer.name)
    }
    return Array.from(m, ([id, name]) => ({ id, name })).sort((a, b) => a.name.localeCompare(b.name))
  }, [available])

  // Filter (farmer + distance) then sort (harvest date / rating / purchases).
  const displayItems = useMemo(() => {
    type WithDist = ProduceListing & { distKm: number | null; distApprox: boolean }
    let items: WithDist[] = filtered.map((item) => {
      let distKm: number | null = null
      let distApprox = false
      if (consumerLat && consumerLng && item.farmer) {
        const coords = farmerCoords(item.farmer)
        if (coords) {
          distKm = haversineKm(consumerLat, consumerLng, coords.lat, coords.lng)
          distApprox = coords.approximate
        }
      }
      const h = harvestMap[item.id]
      return {
        ...item,
        distKm,
        distApprox,
        // Clock source, in order of preference: a logged `harvests` row, else
        // the harvest date/time set on the listing's Edit form. So every produce
        // with a harvest date shows "Harvested 2h ago", not only logged ones.
        latest_harvested_at: h?.at ?? item.harvest_date ?? item.latest_harvested_at ?? null,
        latest_shelf_life_days: h?.shelf ?? item.latest_shelf_life_days ?? item.shelf_life_days ?? null,
      }
    })

    // Filter by farmer.
    if (farmerFilter !== 'all') items = items.filter((i) => i.farmer_id === farmerFilter)
    // Filter by distance (only meaningful once a location is set).
    if (consumerLat && consumerLng && distanceFilter) {
      items = items.filter((i) => i.distKm !== null && i.distKm <= distanceFilter)
    }

    const ts = (iso: string | null | undefined) => {
      const t = iso ? new Date(iso).getTime() : NaN
      return Number.isNaN(t) ? -Infinity : t
    }
    items.sort((a, b) => {
      if (sortBy === 'rating') {
        return (b.rating_avg ?? 0) - (a.rating_avg ?? 0) || (b.review_count ?? 0) - (a.review_count ?? 0)
      }
      if (sortBy === 'purchases') {
        return (b.purchase_count ?? 0) - (a.purchase_count ?? 0)
      }
      // 'fresh' — most recent harvest date/time first.
      return ts(b.latest_harvested_at) - ts(a.latest_harvested_at)
    })
    return items
  }, [filtered, consumerLat, consumerLng, distanceFilter, harvestMap, farmerFilter, sortBy])

  return (
    <main className="min-h-screen bg-[#f8f8f8] pb-12">
      <RoleGateModal />
      <GlobalNav
        activeTab="consumer"
        location={{ name: consumerLocationName, onClick: () => setShowLocationSheet(true) }}
      />

      {/* ── Hero ─────────────────────────────── */}
      <div className="bg-green-900">
        <div className="max-w-3xl mx-auto px-4 pt-8 pb-14">
          {/* My Orders quick link (only when logged in) */}
          <MyOrdersChip />
        </div>
      </div>

      {/* ── Fresh Harvests table + Search card (float over hero) ────── */}
      <div className="max-w-3xl mx-auto px-4 -mt-7 space-y-3">
        {/* Fresh + upcoming harvests near you, above the search box. Sit side by
            side on larger screens, stacked on mobile. Each renders nothing when
            it has no matching harvests / the harvests table isn't present yet. */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 items-start">
          <FreshHarvestsTable />
          <UpcomingHarvestsTable />
        </div>
        <div className="bg-white rounded-2xl shadow-xl p-4 space-y-3">
          <div className="relative">
            <svg className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
              <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35" strokeLinecap="round"/>
            </svg>
            <input
              type="search"
              placeholder={L('Search harvests...', 'కోతలు వెతకండి...')}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl text-base focus:border-green-500 focus:outline-none"
            />
          </div>
          <select
            value={method}
            onChange={(e) => setMethod(e.target.value)}
            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl text-base bg-white focus:border-green-500 focus:outline-none"
          >
            <option value="all">{L('🌿 All methods', 'అన్ని పద్ధతులు')}</option>
            <option value="natural">{L('🌱 Natural', 'సహజం')}</option>
            <option value="organic">{L('🍃 Organic', 'సేంద్రీయ')}</option>
            <option value="low_chemical">{L('⚡ Semi Organic', 'సెమీ ఆర్గానిక్')}</option>
            <option value="chemical">{L('🧪 Chemical', 'రసాయన')}</option>
          </select>

          {/* Sort + farmer filter for the harvest list. */}
          <div className="grid grid-cols-2 gap-3">
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as 'fresh' | 'rating' | 'purchases')}
              className="w-full px-3 py-3 border-2 border-gray-200 rounded-xl text-sm bg-white focus:border-green-500 focus:outline-none"
            >
              <option value="fresh">{L('⏱ Freshest first', 'తాజావి ముందు')}</option>
              <option value="rating">{L('⭐ Top rated', 'టాప్ రేటెడ్')}</option>
              <option value="purchases">{L('🔥 Most bought', 'ఎక్కువ కొన్నవి')}</option>
            </select>
            <select
              value={farmerFilter}
              onChange={(e) => setFarmerFilter(e.target.value)}
              className="w-full px-3 py-3 border-2 border-gray-200 rounded-xl text-sm bg-white focus:border-green-500 focus:outline-none"
            >
              <option value="all">{L('🧑‍🌾 All farmers', 'రైతులందరూ')}</option>
              {farmerOptions.map((f) => (
                <option key={f.id} value={f.id}>{f.name}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* ── Category chips ───────────────────── */}
      <div className="max-w-3xl mx-auto mt-4 px-4">
        <div className="flex gap-2 overflow-x-auto scrollbar-hide pb-1">
          {CATEGORIES.map((chip) => (
            <button
              key={chip.key}
              onClick={() => setCategory(chip.key)}
              className={`flex-shrink-0 px-4 py-2.5 rounded-full text-sm font-semibold border transition-all ${
                category === chip.key
                  ? 'bg-green-700 text-white border-green-700'
                  : 'bg-white text-gray-700 border-gray-200'
              }`}
            >
              {L(chip.en, chip.te)}
            </button>
          ))}
        </div>
      </div>

      {/* ── Distance filter chips (only when location set) ── */}
      {consumerLat && consumerLng && (
        <div className="max-w-3xl mx-auto mt-3 px-4">
          <div className="flex gap-2 overflow-x-auto scrollbar-hide pb-1">
            {([null, 5, 10, 25] as const).map((d) => (
              <button
                key={d ?? 'all'}
                onClick={() => setDistanceFilter(d)}
                className={`flex-shrink-0 px-4 py-2 rounded-full text-sm font-semibold border transition-all ${
                  distanceFilter === d
                    ? 'bg-green-700 text-white border-green-700'
                    : 'bg-white text-gray-700 border-gray-200'
                }`}
              >
                {d === null ? L('All', 'అన్నీ') : `< ${d} km`}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── Available now ────────────────────── */}
      <div className="max-w-3xl mx-auto px-3 mt-6">
        <div className="flex items-end justify-between mb-4">
          <div>
            <h2 className="text-xl font-extrabold text-gray-900">{L('Fresh Harvests', 'తాజా కోతలు')}</h2>
            <p className="text-green-700 font-semibold text-sm leading-tight">
              {L('Fresh from farms nearby', 'దగ్గర్లోని ఫామ్‌ల నుండి తాజాగా')}
            </p>
          </div>
          {!loading && (
            <span className="text-sm font-bold text-gray-400">
              {displayItems.length} {L('items', 'వస్తువులు')}
            </span>
          )}
        </div>

        {loading ? (
          <LoadingSkeleton />
        ) : displayItems.length === 0 ? (
          distanceFilter ? (
            <DistanceEmptyState km={distanceFilter} onClear={() => setDistanceFilter(null)} />
          ) : (
            <EmptyState />
          )
        ) : (
          <div className="grid grid-cols-2 gap-2 auto-rows-fr">
            {displayItems.map((item) => (
              <ProduceCard
                key={item.id}
                item={item}
                distanceKm={'distKm' in item ? (item as ProduceListing & { distKm: number | null }).distKm : null}
                distanceApprox={'distApprox' in item ? (item as ProduceListing & { distApprox: boolean }).distApprox : false}
              />
            ))}
          </div>
        )}
      </div>

      {/* ── Coming soon ──────────────────────── */}
      {!loading && comingSoon.length > 0 && (
        <div className="max-w-3xl mx-auto px-3 mt-10">
          <div className="mb-4">
            <h2 className="text-xl font-extrabold text-gray-900">{L('Coming soon', 'త్వరలో వస్తుంది')}</h2>
            <p className="text-amber-600 font-semibold text-sm">
              {L('Reserve early', 'ముందుగానే రిజర్వ్')}
            </p>
          </div>
          <div className="grid grid-cols-2 gap-2 auto-rows-fr">
            {comingSoon.map((item) => (
              <ComingSoonCard key={item.id} item={item} />
            ))}
          </div>
        </div>
      )}

      {/* ── Demand intent banner ─────────────── */}
      <DemandIntentBanner />

      {/* ── Floating cart button ─────────────── */}
      <CartFab />

      {/* ── Location bottom sheet ─────────────── */}
      {showLocationSheet && (
        <LocationBottomSheet
          onSet={saveConsumerLocation}
          onClose={() => {
            localStorage.setItem('yff_location_prompted', '1')
            setShowLocationSheet(false)
          }}
        />
      )}
    </main>
  )
}

/* ─── Produce card ──────────────────────────────────────── */
function ProduceCard({ item, distanceKm, distanceApprox }: { item: ProduceListing; distanceKm?: number | null; distanceApprox?: boolean }) {
  const emoji       = item.emoji ?? '🌿'
  const produceBg   = PRODUCE_BG[emoji] ?? DEFAULT_PRODUCE_BG
  const method      = item.method?.toLowerCase() ?? 'natural'
  const methodPill  = METHOD_PILL[method]  ?? 'bg-green-600 text-white'
  const methodShort = METHOD_SHORT[method] ?? 'Natural'
  const farmer      = item.farmer
  const farmerHref  = farmer ? `/farmer/${farmer.slug}` : '#'
  const produceHref = `/consumer/produce/${item.id}`
  const unit        = item.unit || 'kg'

  const { tx, lang, L } = useLang()
  const { cart, addItem, setQty } = useCart()
  const { requireAuth } = useConsumerAuth()
  const inCart = cart[item.id]

  const canAdd = !!farmer && !!farmer.phone

  const [liveStock, setLiveStock] = useState<number | null>(item.stock_qty ?? null)
  const [stockMsg, setStockMsg]   = useState('')
  const [adding, setAdding]       = useState(false)

  // All photos for this produce (cover first) — an Amazon/Flipkart-style swipe
  // gallery on the card. activeImg tracks which slide is centred, for the dots.
  const gallery = (item.image_urls && item.image_urls.length ? item.image_urls : (item.image_url ? [item.image_url] : []))
    .filter(Boolean) as string[]
  const [activeImg, setActiveImg] = useState(0)
  const galleryRef = useRef<HTMLDivElement>(null)
  const onGalleryScroll = () => {
    const el = galleryRef.current
    if (!el) return
    setActiveImg(Math.round(el.scrollLeft / el.clientWidth))
  }
  const [showReviews, setShowReviews] = useState(false)

  useEffect(() => { setLiveStock(item.stock_qty ?? null) }, [item.stock_qty])

  const isOutOfStock = liveStock !== null && liveStock <= 0
  const atMax        = liveStock !== null && inCart != null && inCart.qty >= liveStock

  const handleAdd = async () => {
    if (!farmer) return
    requireAuth(() => { void doAdd() })
  }

  const doAdd = async () => {
    if (!farmer) return
    setAdding(true)
    setStockMsg('')

    const { data } = await supabase
      .from('produce_listings')
      .select('stock_qty')
      .eq('id', item.id)
      .single()

    const fresh = data?.stock_qty ?? null
    if (fresh !== null) setLiveStock(fresh)
    setAdding(false)

    if (fresh !== null) {
      if (fresh <= 0) {
        setStockMsg(L('Out of stock', 'అయిపోయింది'))
        return
      }
      const curQty = inCart?.qty ?? 0
      if (curQty >= fresh) {
        setStockMsg(`${L('Maximum available', 'గరిష్ట పరిమాణం')}: ${fresh} ${unit}`)
        return
      }
      if (curQty + 1 > fresh) {
        setStockMsg(L(`Stock updated, only ${fresh} ${unit} available`, `స్టాక్ మారింది, కేవలం ${fresh} ${unit} అందుబాటులో`))
        return
      }
    }

    addItem({
      listingId: item.id,
      name: item.name,
      variety: item.variety,
      emoji: item.emoji,
      unit,
      stockQty: fresh != null ? fresh : (item.stock_qty ?? undefined),
      pricePerKg: item.price_tier_1_price,
      priceTier1Qty: item.price_tier_1_qty,
      priceTier1Price: item.price_tier_1_price,
      priceTier2Qty: item.price_tier_2_qty,
      priceTier2Price: item.price_tier_2_price,
      priceTier3Price: item.price_tier_3_price,
      farmerId: farmer.id,
      farmerName: farmer.name,
      farmerPhone: farmer.phone,
      farmerVillage: farmer.village,
      farmerSlug: farmer.slug,
      farmerPickupLocations: farmer.pickup_locations ?? [],
      farmerPickupSlots: normalizePickupSchedule(farmer.pickup_slots, farmer.pickup_locations ?? []),
    }, 1)
  }

  const handleInc = () => {
    if (liveStock !== null && inCart.qty >= liveStock) {
      setStockMsg(`${L('Maximum available', 'గరిష్ట పరిమాణం')}: ${liveStock} ${unit}`)
      return
    }
    setStockMsg('')
    setQty(item.id, inCart.qty + 1)
  }

  return (
    <div className="bg-white rounded-xl overflow-hidden shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex flex-col h-full">
      {/* Image — fixed 160px. Multiple photos become a swipe gallery (swipe
          right-to-left for the rest); method pill top-right, dots bottom-centre. */}
      <div className="relative h-40 w-full flex-shrink-0">
        {gallery.length ? (
          <div
            ref={galleryRef}
            onScroll={onGalleryScroll}
            className="flex h-full w-full overflow-x-auto snap-x snap-mandatory scrollbar-hide"
          >
            {gallery.map((url) => (
              <Link
                key={url}
                href={produceHref}
                className="snap-center shrink-0 w-full h-40 block"
              >
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={url} alt={item.name} loading="lazy" className="w-full h-full object-cover" />
              </Link>
            ))}
          </div>
        ) : (
          <Link
            href={produceHref}
            className="w-full h-full flex items-center justify-center"
            style={{ backgroundColor: produceBg }}
          >
            <span className="text-5xl">{emoji}</span>
          </Link>
        )}
        <span
          className={`absolute top-2 right-2 ${methodPill} text-[10px] font-bold rounded-full px-1.5 py-0.5 shadow-sm`}
        >
          {methodShort}
        </span>
        <div className="absolute top-2 left-2">
          <ShareButton
            info={{
              id: item.id,
              name: item.name,
              variety: item.variety,
              emoji: item.emoji,
              method: item.method,
              pricePerUnit: item.price_tier_1_price,
              unit,
              farmerName: farmer?.name,
              farmerVillage: farmer?.village,
            }}
          />
        </div>
        {gallery.length > 1 && (
          <div className="absolute bottom-2 left-0 right-0 flex justify-center gap-1.5 pointer-events-none">
            {gallery.map((_, i) => (
              <span
                key={i}
                className={`h-1.5 rounded-full transition-all ${
                  i === activeImg ? 'w-4 bg-white' : 'w-1.5 bg-white/60'
                }`}
              />
            ))}
          </div>
        )}
      </div>

      {/* Content */}
      <div className="p-3 flex flex-col flex-1 min-w-0">
        {/* Name + variety — single line each, ellipsis on overflow */}
        <Link href={produceHref} className="block min-w-0">
          <h3 className="font-bold text-[15px] leading-[1.2] text-gray-900 truncate">
            {localizeName(item.name, lang)}
          </h3>
          {item.variety && (
            <p className="text-[12px] text-[#666] truncate mt-0.5">{localizeName(item.variety, lang)}</p>
          )}
        </Link>

        {/* Harvest clock — "Harvested 2 hours ago", from this produce's latest
            harvest. Only shows once a harvest has been logged. */}
        {item.latest_harvested_at && (
          <div className="flex items-center gap-1.5 mt-1 flex-wrap">
            <span className="inline-flex items-center gap-1 text-[11px] font-bold text-green-700 bg-green-50 rounded-full px-2 py-0.5">
              ⏱ {harvestClock(item.latest_harvested_at, L)}
            </span>
            {(() => {
              const fresh = freshnessLabel(item.latest_harvested_at, item.latest_shelf_life_days, L)
              return fresh ? <span className="text-[11px] font-semibold text-amber-700">{fresh}</span> : null
            })()}
          </div>
        )}

        {/* Farmer + location, with a small tappable "View profile" link */}
        {farmer && (
          <div className="flex items-center justify-between gap-1.5 mt-1">
            <p className="text-[11px] text-[#666] truncate min-w-0">
              👨‍🌾 {farmer.name} · {farmer.village}
            </p>
            <Link
              href={farmerHref}
              className="flex-shrink-0 text-[11px] font-semibold text-[#1a5c2a] whitespace-nowrap active:opacity-70"
            >
              {tx.viewProfile} ›
            </Link>
          </div>
        )}

        {/* Distance (only when location set) */}
        {distanceKm != null && (
          <p className="text-[11px] font-semibold text-blue-700 truncate mt-0.5">
            📍 {distanceApprox ? '~' : ''}{formatDistance(distanceKm)} away
          </p>
        )}

        {/* Buyer rating — tap to read reviews. Only when at least one exists. */}
        {(item.review_count ?? 0) > 0 && item.rating_avg != null && (
          <button
            type="button"
            onClick={() => setShowReviews(true)}
            className="flex items-center gap-1 mt-1 active:opacity-70"
          >
            <span className="inline-flex items-center gap-0.5 bg-green-700 text-white text-[11px] font-bold rounded px-1.5 py-0.5">
              {item.rating_avg.toFixed(1)} ★
            </span>
            <span className="text-[11px] text-[#666] underline">
              {item.review_count} {item.review_count === 1 ? L('review', 'సమీక్ష') : L('reviews', 'సమీక్షలు')}
            </span>
          </button>
        )}

        {/* Price */}
        <div className="mt-1.5">
          <span className="font-extrabold text-[18px] text-[#1a5c2a]">
            {item.price_tier_1_price ? `₹${item.price_tier_1_price}` : '—'}
            <span className="text-[12px] font-medium text-[#666]">/{unit}</span>
          </span>
        </div>

        {/* Stock badge */}
        {liveStock != null && (
          <div className="flex flex-wrap items-center gap-1.5 mt-1.5">
            {liveStock != null && (
              <span
                className={`text-[11px] font-medium rounded-full px-2 py-0.5 ${
                  liveStock === 0 ? 'bg-red-50 text-red-600' : 'bg-[#f5f5f5] text-[#666]'
                }`}
              >
                {liveStock === 0 ? 'Out of stock' : `${liveStock} ${unit} left`}
              </span>
            )}
          </div>
        )}

        {/* Stock warning */}
        {stockMsg && (
          <p className="text-[11px] text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-2 py-1 leading-snug text-center mt-1.5">
            {stockMsg}
          </p>
        )}

        {/* CTA — pinned to bottom of card, fixed 40px height */}
        <div className="mt-auto pt-2.5">
          {!canAdd ? (
            <Link
              href={farmerHref}
              className="flex items-center justify-center w-full h-10 bg-[#1a5c2a] text-white font-bold rounded-xl text-sm"
            >
              {L('View', 'చూడండి')}
            </Link>
          ) : isOutOfStock ? (
            <button
              disabled
              className="w-full h-10 bg-gray-200 text-gray-500 font-bold rounded-xl text-sm cursor-not-allowed"
            >
              {L('Out of stock', 'అయిపోయింది')}
            </button>
          ) : !inCart ? (
            <button
              onClick={handleAdd}
              disabled={adding}
              className="w-full h-10 bg-[#1a5c2a] active:opacity-90 text-white font-bold rounded-xl text-sm disabled:opacity-60 whitespace-nowrap"
            >
              {adding ? L('Checking...', 'తనిఖీ') : L('+ Add', 'చేర్చు')}
            </button>
          ) : (
            <div className="flex items-center justify-between bg-green-50 border border-green-200 rounded-xl h-10 px-2">
              <button
                onClick={() => { setQty(item.id, inCart.qty - 1); setStockMsg('') }}
                className="w-7 h-7 rounded-lg bg-white border border-green-300 text-green-800 text-lg font-bold leading-none"
                aria-label="Decrease"
              >
                −
              </button>
              <span className="font-extrabold text-green-900 text-sm">
                {inCart.qty} {unit}
              </span>
              <button
                onClick={handleInc}
                disabled={atMax}
                className={`w-7 h-7 rounded-lg text-lg font-bold leading-none transition-colors ${
                  atMax
                    ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                    : 'bg-green-700 text-white'
                }`}
                aria-label="Increase"
              >
                +
              </button>
            </div>
          )}
        </div>
      </div>

      {showReviews && (
        <ProduceReviewsModal
          listingId={item.id}
          produceName={localizeName(item.name, lang)}
          onClose={() => setShowReviews(false)}
        />
      )}
    </div>
  )
}

