/* ─── Location bottom sheet ─────────────────────────────────── */
function LocationBottomSheet({
  onSet,
  onClose,
}: {
  onSet: (lat: number, lng: number, name: string) => void
  onClose: () => void
}) {
  const { L } = useLang()
  const [gpsStatus, setGpsStatus] = useState<'idle' | 'loading' | 'error'>('idle')
  const [gpsError, setGpsError]   = useState('')

  const handleGPS = () => {
    if (!navigator.geolocation) {
      setGpsError(L('GPS not supported on this device', 'GPS అందుబాటులో లేదు'))
      return
    }
    setGpsStatus('loading')
    setGpsError('')
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords
        const name = nearestTown(latitude, longitude)
        onSet(latitude, longitude, name)
      },
      (err) => {
        setGpsStatus('error')
        setGpsError(
          err.code === 1
            ? L('Location access denied. Search your town below.', 'లొకేషన్ అనుమతి లేదు. పట్టణం వెతకండి.')
            : L('Could not get GPS. Search your town below.', 'GPS రాలేదు. పట్టణం వెతకండి.')
        )
      },
      { timeout: 12000, enableHighAccuracy: true },
    )
  }

  return (
    <div className="fixed inset-0 z-[100] bg-black/50 flex items-end justify-center">
      <div className="bg-white w-full max-w-md rounded-t-3xl p-5 space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="font-extrabold text-gray-900 text-lg leading-tight">
              {L('Where are you?', 'మీరు ఎక్కడ ఉన్నారు?')}
            </h2>
            <p className="text-xs text-gray-500 mt-0.5">
              {L('See harvests from farmers near you', 'దగ్గరలోని రైతుల కోతలు చూడండి')}
            </p>
          </div>
          <button onClick={onClose} className="text-gray-400 text-3xl leading-none p-1">×</button>
        </div>

        {/* GPS button */}
        <button
          onClick={handleGPS}
          disabled={gpsStatus === 'loading'}
          className="w-full flex items-center justify-center gap-2 bg-green-700 text-white font-bold py-4 rounded-xl text-base active:bg-green-800 disabled:opacity-60"
        >
          {gpsStatus === 'loading' ? (
            <>
              <span className="animate-spin inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full" />
              {L('Detecting...', 'వెతుకుతోంది')}
            </>
          ) : (
            <>{L('📍 Use my current location', 'నా లొకేషన్ వాడండి')}</>
          )}
        </button>

        {gpsError && (
          <p className="text-xs text-red-600 bg-red-50 rounded-xl px-3 py-2 leading-snug">{gpsError}</p>
        )}

        {/* Divider */}
        <div className="flex items-center gap-3">
          <div className="flex-1 border-t border-gray-200" />
          <span className="text-xs text-gray-400 font-semibold">{L('OR', 'లేదా')}</span>
          <div className="flex-1 border-t border-gray-200" />
        </div>

        {/* Search input */}
        <div>
          <label className="text-xs font-bold text-gray-700 uppercase tracking-wide block mb-2">
            {L('Search your location', 'లొకేషన్ వెతకండి')}
          </label>
          <p className="text-[11px] text-gray-500 mb-2">
            {L('Type any city, town or village in AP / Telangana', 'ఆంధ్రప్రదేశ్ / తెలంగాణలో ఏ పట్టణమైనా టైప్ చేయండి')}
          </p>
          <LocationSearch
            placeholder="e.g. Visakhapatnam, Hyderabad, Eluru..."
            onSelect={(lat, lng, name) => onSet(lat, lng, name)}
          />
        </div>

        <button
          onClick={onClose}
          className="w-full text-sm text-gray-500 py-2"
        >
          {L('Skip for now', 'తర్వాత చేస్తాను')}
        </button>
      </div>
    </div>
  )
}

/* ─── Demand intent banner ──────────────────────────────────── */
function DemandIntentBanner() {
  const { L } = useLang()
  const { consumer } = useConsumerAuth()
  const [open, setOpen] = useState(false)
  const [crop, setCrop] = useState('')
  const [qty, setQty] = useState('')
  const [date, setDate] = useState('')
  const [location, setLocation] = useState('')
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [loading, setLoading] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const [error, setError] = useState('')

  // Pre-fill name/phone from the logged-in consumer once known, so their raised
  // intent is tied to (and appears under) their account on the My Intents page.
  useEffect(() => {
    if (consumer) {
      setName((n) => n || consumer.name || '')
      setPhone((p) => p || consumer.phone || '')
    }
  }, [consumer])

  const handleSubmit = async () => {
    if (!crop.trim() || !name.trim() || !phone.trim()) {
      setError(L('Please fill crop name, your name, and phone number.', 'పంట పేరు, మీ పేరు, ఫోన్ నంబర్ నింపండి.'))
      return
    }
    setLoading(true)
    setError('')
    const { supabase: sb } = await import('@/lib/supabase')
    const { error: err } = await sb.from('demand_intents').insert({
      crop_name: crop.trim(),
      quantity_kg: qty ? Number(qty) : null,
      needed_by_date: date || null,
      delivery_location: location.trim() || null,
      requester_name: name.trim(),
      requester_phone: phone.trim(),
      consumer_id: consumer?.id ?? null,
      region_slug: localStorage.getItem('yff_consumer_location_name')?.toLowerCase().replace(/\s+/g, '') || 'tadepalligudem',
    })
    setLoading(false)
    if (err) { setError(err.message); return }
    setSubmitted(true)
  }

  return (
    <div className="max-w-3xl mx-auto px-4 mt-10 mb-4">
      <div className="bg-amber-50 border-2 border-amber-200 rounded-2xl p-4">
        <div className="flex items-start gap-3">
          <span className="text-2xl">📣</span>
          <div className="flex-1 min-w-0">
            <h3 className="font-extrabold text-amber-900 text-base leading-tight">
              {L('Raise a Demand Intent', 'డిమాండ్ నమోదు')}
            </h3>
            <p className="text-amber-700 text-sm mt-1 leading-snug">
              {L("Let local farmers know what you need — they'll reach out when available.", 'స్థానిక రైతులకు మీకు ఏమి కావాలో తెలియజేయండి')}
            </p>
          </div>
        </div>

        {!open && !submitted && (
          <div className="mt-4 space-y-2">
            <button
              onClick={() => setOpen(true)}
              className="w-full bg-amber-600 text-white font-bold py-3.5 rounded-xl text-sm flex items-center justify-center gap-2"
            >
              <span className="text-lg leading-none">+</span>
              {L('Raise Intent', 'డిమాండ్ నమోదు')}
            </button>
            {consumer && (
              <Link
                href="/consumer/intents"
                className="w-full block text-center text-amber-800 font-semibold text-sm py-2.5 rounded-xl border-2 border-amber-300 active:bg-amber-100"
              >
                📋 {L('My raised intents', 'నా డిమాండ్‌లు')}
              </Link>
            )}
          </div>
        )}

        {submitted && (
          <div className="mt-4 text-center py-3">
            <p className="text-green-700 font-bold text-base">{L('✓ Intent raised!', 'నమోదైంది!')}</p>
            <p className="text-green-600 text-sm mt-1">
              {L('Farmers in your area will be notified.', 'మీ ప్రాంతంలోని రైతులకు తెలియజేస్తాము.')}
            </p>
            <Link href="/consumer/intents" className="inline-block mt-2 text-amber-800 font-semibold text-sm underline">
              {L('View my intents →', 'నా డిమాండ్‌లు చూడండి →')}
            </Link>
          </div>
        )}

        {open && !submitted && (
          <div className="mt-4 space-y-3">
            <input
              type="text"
              placeholder={L('Crop name * (e.g. Tomato', 'టమాటా)')}
              value={crop}
              onChange={(e) => setCrop(e.target.value)}
              className="w-full border border-amber-200 rounded-xl px-4 py-3 text-sm bg-white focus:border-amber-500 focus:outline-none"
            />
            <div className="grid grid-cols-2 gap-2">
              <input
                type="number"
                placeholder={L('Quantity (kg)', 'పరిమాణం')}
                value={qty}
                onChange={(e) => setQty(e.target.value)}
                className="border border-amber-200 rounded-xl px-3 py-3 text-sm bg-white focus:border-amber-500 focus:outline-none"
              />
              <input
                type="date"
                value={date}
                onChange={(e) => setDate(e.target.value)}
                className="border border-amber-200 rounded-xl px-3 py-3 text-sm bg-white focus:border-amber-500 focus:outline-none"
              />
            </div>
            <input
              type="text"
              placeholder={L('Delivery location', 'డెలివరీ స్థలం')}
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              className="w-full border border-amber-200 rounded-xl px-4 py-3 text-sm bg-white focus:border-amber-500 focus:outline-none"
            />
            <input
              type="text"
              placeholder={L('Your name *', 'మీ పేరు')}
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full border border-amber-200 rounded-xl px-4 py-3 text-sm bg-white focus:border-amber-500 focus:outline-none"
            />
            <input
              type="tel"
              placeholder={L('Your WhatsApp number *', 'మీ వాట్సాప్ నంబర్')}
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="w-full border border-amber-200 rounded-xl px-4 py-3 text-sm bg-white focus:border-amber-500 focus:outline-none"
            />

            {error && (
              <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
            )}

            <div className="flex gap-2">
              <button
                onClick={() => { setOpen(false); setError('') }}
                className="flex-1 border-2 border-gray-300 text-gray-600 font-semibold py-3 rounded-xl text-sm"
              >
                {L('Cancel', 'రద్దు')}
              </button>
              <button
                onClick={handleSubmit}
                disabled={loading}
                className="flex-1 bg-amber-600 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50"
              >
                {loading ? L('Submitting...', 'నమోదు అవుతోంది') : L('Submit', 'నమోదు')}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

import { supabase } from '@/lib/supabase'
import { NextRequest, NextResponse } from 'next/server'
import { purchaseCountsFor } from '@/lib/purchaseCounts'

export const dynamic = 'force-dynamic'
export const fetchCache = 'force-no-store'

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const status = searchParams.get('status') ?? 'available'

  const { data: produce, error } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('status', status)
    .order('created_at', { ascending: false })

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!produce?.length) return NextResponse.json([])

  const farmerIds = [...new Set(produce.map((p) => p.farmer_id))]

  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, village, slug, phone, method, region_slug, pickup_locations, pickup_slots, lat, lng')
    .in('id', farmerIds)
    .eq('active', true)

  const farmerMap = Object.fromEntries((farmers ?? []).map((f) => [f.id, f]))

  const result = produce
    .map((p) => ({ ...p, farmer: farmerMap[p.farmer_id] ?? null }))
    .filter((p) => p.farmer !== null)

  // Popularity count for the consumer "sort by Purchases" option.
  const counts = await purchaseCountsFor(result.map((p) => p.id as string))
  const withCounts = result.map((p) => ({ ...p, purchase_count: counts[p.id as string] ?? 0 }))

  return NextResponse.json(withCounts)
}

// Harvest model helpers — the "Harvested 2 hours ago" clock and freshness math.
// A produce_listing is the template; a `harvests` row is one actual pick with a
// harvested_at timestamp + shelf_life_days. See scripts/harvests-migration.sql.

export type Harvest = {
  id: string
  produce_listing_id: string
  farmer_id?: string | null
  harvested_at: string
  shelf_life_days?: number | null
  approx_quantity?: number | null
  unit?: string | null
  notes?: string | null
}

type Tr = (en: string, te: string) => string
const en: Tr = (e) => e

// "just now" / "12 min ago" / "2 hours ago" / "yesterday" / "3 days ago".
// For a future harvest (farmer logged an upcoming pick) → "in 2 hours" etc.
function relTime(iso: string, L: Tr): string {
  const then = new Date(iso).getTime()
  if (isNaN(then)) return ''
  const diffMs = Date.now() - then
  const future = diffMs < 0
  const mins = Math.floor(Math.abs(diffMs) / 60000)

  if (mins < 1) return L('just now', 'ఇప్పుడే')
  const fmt = (n: number, unitEn: string, unitTe: string) =>
    future
      ? `${L('in', 'లో')} ${n} ${L(unitEn, unitTe)}`
      : `${n} ${L(unitEn, unitTe)} ${L('ago', 'క్రితం')}`

  if (mins < 60) return fmt(mins, mins === 1 ? 'min' : 'mins', 'నిమి')
  const hrs = Math.floor(mins / 60)
  if (hrs < 24) return fmt(hrs, hrs === 1 ? 'hour' : 'hours', 'గం')
  const days = Math.floor(hrs / 24)
  if (days === 1) return future ? L('tomorrow', 'రేపు') : L('yesterday', 'నిన్న')
  return fmt(days, 'days', 'రోజులు')
}

// The headline clock shown on a harvest, e.g. "🌾 Harvested 2 hours ago".
export function harvestClock(harvestedAt: string, L: Tr = en): string {
  const rel = relTime(harvestedAt, L)
  if (!rel) return ''
  const future = new Date(harvestedAt).getTime() > Date.now()
  return future
    ? `${L('Harvest expected', 'కోత అంచనా')} ${rel}`
    : `${L('Harvested', 'కోసింది')} ${rel}`
}

// Whole days (rounded up) a harvest has been off the plant. Day 0 = picked today.
export function harvestAgeDays(harvestedAt: string): number {
  const diffMs = Date.now() - new Date(harvestedAt).getTime()
  if (isNaN(diffMs) || diffMs < 0) return 0
  return Math.floor(diffMs / 86_400_000)
}

// Freshness from shelf life: days left before it spoils, and whether it's past.
// Returns null when no shelf life is set (can't compute).
export function freshnessLeftDays(harvestedAt: string, shelfLifeDays?: number | null): number | null {
  if (shelfLifeDays == null || shelfLifeDays <= 0) return null
  const left = shelfLifeDays - harvestAgeDays(harvestedAt)
  return left
}

// Short freshness label, e.g. "3 days fresh left" / "Use today" / "Past best".
export function freshnessLabel(harvestedAt: string, shelfLifeDays?: number | null, L: Tr = en): string | null {
  const left = freshnessLeftDays(harvestedAt, shelfLifeDays)
  if (left == null) return null
  if (left < 0) return L('Past best', 'గడువు ముగిసింది')
  if (left === 0) return L('Use today', 'ఈరోజే వాడండి')
  if (left === 1) return L('1 day fresh left', '1 రోజు తాజా')
  return `${left} ${L('days fresh left', 'రోజులు తాజా')}`
}

