    .filter(Boolean) as string[]
  const farmerHref = farmer ? `/farmer/${farmer.slug}` : '#'
  const canAdd = !!farmer && !!farmer.phone
  const inCart = cart[harvest.id]
  const isOutOfStock = liveStock !== null && liveStock <= 0
